INSERT INTO public.fields (id, slug, name, description, icon, post_count, "order") VALUES ('10000000-0000-4000-8000-000000000001'::uuid, 'reader-guide', 'Hướng dẫn cho người mới', 'Bộ bài viết dành cho độc giả: làm quen blog, đăng ký, đăng nhập, khôi phục mật khẩu và các thói quen an toàn.', 'book-open', 0, -1) ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, icon = EXCLUDED.icon, "order" = EXCLUDED."order";
INSERT INTO public.categories (id, slug, name, description, field_id, post_count, "order") VALUES ('10000000-0000-4000-8000-000000000011'::uuid, 'reader-lam-quen', 'Làm quen với blog', 'Tổng quan PLC Việt Nam, cấu trúc nội dung và cách tìm bài.', '10000000-0000-4000-8000-000000000001'::uuid, 0, 0) ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, field_id = EXCLUDED.field_id, "order" = EXCLUDED."order";
INSERT INTO public.categories (id, slug, name, description, field_id, post_count, "order") VALUES ('10000000-0000-4000-8000-000000000012'::uuid, 'reader-tai-khoan', 'Tài khoản & đăng nhập', 'Đăng ký, đăng nhập email/Google, đăng xuất và phiên làm việc.', '10000000-0000-4000-8000-000000000001'::uuid, 0, 1) ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, field_id = EXCLUDED.field_id, "order" = EXCLUDED."order";
INSERT INTO public.categories (id, slug, name, description, field_id, post_count, "order") VALUES ('10000000-0000-4000-8000-000000000013'::uuid, 'reader-mat-khau', 'Mật khẩu & xác nhận email', 'Quên mật khẩu, đặt lại mật khẩu, xác nhận và gửi lại email.', '10000000-0000-4000-8000-000000000001'::uuid, 0, 2) ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, field_id = EXCLUDED.field_id, "order" = EXCLUDED."order";
INSERT INTO public.tags (id, slug, name, post_count) VALUES ('10000000-0000-4000-8000-000000000099'::uuid, 'huong-dan-doc-gia', 'Hướng dẫn độc giả', 0) ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name;
INSERT INTO public.posts (id, slug, title, excerpt, content, category_id, field_id, status, published_at, updated_at, reading_time, seo_title, seo_description, seo_keywords, view_count) VALUES ('10000000-0000-4000-8000-000000001001'::uuid, 'reader-chao-mung-va-cach-su-dung-blog', 'Chào mừng bạn đến với PLC Việt Nam — Bắt đầu như một độc giả', 'Tổng quan về blog, cách tìm bài viết, và những việc bạn có thể làm với tài khoản độc giả (reader).', $body$<h2>Chúng tôi xây dựng blog này cho ai?</h2><p>PLC Việt Nam là không gian chia sẻ kiến thức về PLC, SCADA, Siemens và tự động hóa công nghiệp. Phần lớn nội dung <strong>có thể đọc miễn phí</strong> mà không cần đăng nhập. Tài khoản giúp bạn đồng bộ trải nghiệm (ví dụ bình luận hoặc các tính năng cộng đồng được bật trên hệ thống).</p><h2>Bạn sẽ thấy gì trên trang chủ?</h2><ul><li><strong>Bài viết mới</strong>: các bài cập nhật gần đây.</li><li><strong>Lĩnh vực</strong>: nhóm chủ đề lớn; trong mỗi lĩnh vực có <strong>danh mục</strong> và <strong>bài viết</strong>.</li><li><strong>Thư viện sách</strong>: tài liệu tham khảo được giới thiệu trên blog.</li></ul><h2>Điều hướng nhanh</h2><p>Dùng menu trên cùng hoặc <strong>cây chủ đề</strong> ở sidebar (màn hình lớn) để mở đúng lĩnh vực. Trên điện thoại, mở biểu tượng menu để xem cùng một cấu trúc.</p><h2>Gợi ý lộ trình cho người mới</h2><ol><li>Đọc nhanh các bài trong mục <em>Hướng dẫn cho người mới</em> (lĩnh vực bạn đang xem).</li><li>Chọn một lĩnh vực kỹ thuật (PLC, SCADA, Siemens…) theo mục tiêu của bạn.</li><li>Dùng <strong>Tìm kiếm</strong> khi bạn đã có từ khóa cụ thể.</li></ol><p>Nếu bạn chỉ muốn đọc, hãy bắt đầu từ các bài trong danh mục <strong>Làm quen với blog</strong> và <strong>Đọc bài &amp; tìm kiếm</strong>.</p>$body$::text, '10000000-0000-4000-8000-000000000011'::uuid, '10000000-0000-4000-8000-000000000001'::uuid, 'published', '2026-05-10T08:00:00Z'::timestamptz, '2026-05-10T08:00:00Z'::timestamptz, 1, 'Chào mừng độc giả mới — PLC Việt Nam', 'Hướng dẫn tổng quan cho người mới: cấu trúc blog, lĩnh vực, danh mục và lộ trình đọc.', ARRAY['PLC Việt Nam','hướng dẫn','độc giả','blog']::text[], 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, excerpt = EXCLUDED.excerpt, content = EXCLUDED.content, category_id = EXCLUDED.category_id, field_id = EXCLUDED.field_id, status = EXCLUDED.status, published_at = EXCLUDED.published_at, updated_at = EXCLUDED.updated_at, reading_time = EXCLUDED.reading_time, seo_title = EXCLUDED.seo_title, seo_description = EXCLUDED.seo_description, seo_keywords = EXCLUDED.seo_keywords;
INSERT INTO public.post_tags (post_id, tag_id) SELECT id, '10000000-0000-4000-8000-000000000099'::uuid FROM public.posts WHERE slug = 'reader-chao-mung-va-cach-su-dung-blog' ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, slug, title, excerpt, content, category_id, field_id, status, published_at, updated_at, reading_time, seo_title, seo_description, seo_keywords, view_count) VALUES ('10000000-0000-4000-8000-000000001002'::uuid, 'reader-doc-bai-tim-kiem-va-cau-truc-noi-dung', 'Đọc bài, tìm kiếm và hiểu cấu trúc nội dung', 'Cách mở bài viết, di chuyển giữa lĩnh vực — danh mục — bài viết, và dùng ô tìm kiếm hiệu quả.', $body$<h2>Cấu trúc URL thân thiện</h2><p>Nội dung được tổ chức theo ba cấp: <strong>Lĩnh vực → Danh mục → Bài viết</strong>. Đường dẫn thường có dạng <code>/fields/[lĩnh-vực]/[danh-mục]/[bài-viết]</code>, giúp bạn chia sẻ liên kết trực tiếp tới một bài cụ thể.</p><h2>Mở và đọc bài</h2><ul><li>Ở trang danh sách trong danh mục, chọn tiêu đề bài để vào trang chi tiết.</li><li>Trên trang bài viết, bạn xem phần <strong>tóm tắt</strong>, <strong>nội dung</strong>, thông tin tác giả và (nếu được bật) <strong>bình luận</strong>.</li><li>Thời gian đọc ước lượng giúp bạn cân nhắc trước khi bắt đầu.</li></ul><h2>Tìm kiếm toàn site</h2><p>Dùng mục <strong>Tìm kiếm</strong> trên header. Gõ từ khóa ngắn, ưu tiên thuật ngữ kỹ thuật (ví dụ “Modbus”, “TIA Portal”, “PID”). Kết quả gồm bài viết và có thể cả sách, tùy cấu hình dữ liệu.</p><h2>Mẹo cho người mới</h2><ul><li>Đọc <strong>phần đầu bài</strong> và <strong>mục lục ẩn</strong> (nếu tác giả dùng tiêu đề phụ) trước khi đọc sâu.</li><li>Lưu tab trình duyệt hoặc bookmark các bài quan trọng để học dần.</li><li>Khi gặp thuật ngữ lạ, thử tìm thêm trong cùng lĩnh vực hoặc qua ô tìm kiếm.</li></ul>$body$::text, '10000000-0000-4000-8000-000000000011'::uuid, '10000000-0000-4000-8000-000000000001'::uuid, 'published', '2026-05-10T08:15:00Z'::timestamptz, '2026-05-10T08:15:00Z'::timestamptz, 1, 'Đọc bài và tìm kiếm trên PLC Việt Nam', 'Hướng dẫn cấu trúc nội dung, cách mở bài viết và dùng tìm kiếm.', ARRAY['tìm kiếm','đọc blog','danh mục']::text[], 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, excerpt = EXCLUDED.excerpt, content = EXCLUDED.content, category_id = EXCLUDED.category_id, field_id = EXCLUDED.field_id, status = EXCLUDED.status, published_at = EXCLUDED.published_at, updated_at = EXCLUDED.updated_at, reading_time = EXCLUDED.reading_time, seo_title = EXCLUDED.seo_title, seo_description = EXCLUDED.seo_description, seo_keywords = EXCLUDED.seo_keywords;
INSERT INTO public.post_tags (post_id, tag_id) SELECT id, '10000000-0000-4000-8000-000000000099'::uuid FROM public.posts WHERE slug = 'reader-doc-bai-tim-kiem-va-cau-truc-noi-dung' ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, slug, title, excerpt, content, category_id, field_id, status, published_at, updated_at, reading_time, seo_title, seo_description, seo_keywords, view_count) VALUES ('10000000-0000-4000-8000-000000001003'::uuid, 'reader-dang-ky-tai-khoan-email-va-xac-nhan', 'Đăng ký tài khoản bằng email — Từng bước và xác nhận', 'Quy trình tạo tài khoản, kiểm tra hộp thư, xác nhận email và các lưu ý bảo mật cơ bản.', $body$<h2>Khi nào nên đăng ký?</h2><p>Khi bạn muốn <strong>bình luận</strong>, lưu tùy chọn cá nhân hoặc dùng các tính năng yêu cầu định danh. Đăng ký không thay thế việc đọc miễn phí các bài công khai.</p><h2>Các bước đăng ký</h2><ol><li>Mở trang <strong>Đăng ký</strong> từ menu tài khoản hoặc liên kết trên trang đăng nhập.</li><li>Nhập <strong>email</strong> hợp lệ và <strong>mật khẩu</strong> theo chính sách của hệ thống (độ dài tối thiểu, chữ hoa, chữ thường, chữ số và ký tự đặc biệt).</li><li>Hoàn tất <strong>xác thực người thật</strong> (CAPTCHA) nếu trang yêu cầu — giúp giảm spam và tấn công tự động.</li><li>Gửi biểu mẫu và kiểm tra email để <strong>xác nhận địa chỉ</strong>.</li></ol><h2>Sau khi gửi đăng ký</h2><ul><li>Mở email từ nhà cung cấp xác thực và bấm liên kết xác nhận trong thời gian hiệu lực.</li><li>Nếu không thấy thư, kiểm tra <strong>Hộp thư rác / Spam</strong> và <strong>Thư quảng cáo</strong>.</li><li>Bạn có thể dùng chức năng <strong>gửi lại email xác nhận</strong> (nếu có) với <strong>thời gian chờ giữa các lần gửi</strong> để bảo vệ hệ thống.</li></ul><h2>Lưu ý riêng tư</h2><p>Dùng email cá nhân bạn kiểm soát được. Tránh dùng email dùng chung công ty nếu bạn không chắc chính sách IT cho phép nhận thư xác thực bên ngoài.</p><h2>An toàn tài khoản</h2><p>Đừng chia sẻ mật khẩu. Tránh đăng ký trên thiết bị công cộng mà không đăng xuất sau đó. Nếu nghi ngờ lộ mật khẩu, hãy <strong>đổi mật khẩu</strong> sau khi đăng nhập hoặc dùng luồng <strong>Quên mật khẩu</strong>.</p>$body$::text, '10000000-0000-4000-8000-000000000012'::uuid, '10000000-0000-4000-8000-000000000001'::uuid, 'published', '2026-05-10T08:30:00Z'::timestamptz, '2026-05-10T08:30:00Z'::timestamptz, 1, 'Đăng ký tài khoản và xác nhận email', 'Hướng dẫn đăng ký bằng email, xác nhận tài khoản và lưu ý bảo mật.', ARRAY['đăng ký','xác nhận email','tài khoản']::text[], 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, excerpt = EXCLUDED.excerpt, content = EXCLUDED.content, category_id = EXCLUDED.category_id, field_id = EXCLUDED.field_id, status = EXCLUDED.status, published_at = EXCLUDED.published_at, updated_at = EXCLUDED.updated_at, reading_time = EXCLUDED.reading_time, seo_title = EXCLUDED.seo_title, seo_description = EXCLUDED.seo_description, seo_keywords = EXCLUDED.seo_keywords;
INSERT INTO public.post_tags (post_id, tag_id) SELECT id, '10000000-0000-4000-8000-000000000099'::uuid FROM public.posts WHERE slug = 'reader-dang-ky-tai-khoan-email-va-xac-nhan' ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, slug, title, excerpt, content, category_id, field_id, status, published_at, updated_at, reading_time, seo_title, seo_description, seo_keywords, view_count) VALUES ('10000000-0000-4000-8000-000000001004'::uuid, 'reader-dang-nhap-email-mat-khau-va-google', 'Đăng nhập bằng email/mật khẩu hoặc Google', 'Hai cách đăng nhập phổ biến, cách nhận biết phiên đăng nhập thành công và xử lý sự cố thường gặp.', $body$<h2>Đăng nhập bằng email và mật khẩu</h2><ol><li>Mở trang <strong>Đăng nhập</strong>.</li><li>Nhập email đã đăng ký và mật khẩu.</li><li>Nếu có CAPTCHA, hoàn tất trước khi gửi.</li><li>Sau khi thành công, bạn được chuyển về trang trước đó hoặc trang chủ.</li></ol><h2>Đăng nhập bằng Google</h2><p>Chọn nút đăng nhập Google (nếu được bật). Trình duyệt mở luồng OAuth của Google; sau khi đồng ý, hệ thống tạo hoặc liên kết phiên theo chính sách của blog. Bạn nên dùng <strong>một tài khoản Google ổn định</strong> để tránh tạo nhiều hồ sơ trùng lặp.</p><h2>Sau khi đăng nhập</h2><ul><li>Biểu tượng hoặc menu tài khoản hiển thị <strong>tên / email</strong> tóm tắt.</li><li>Một số thao tác (bình luận, chỉnh sửa nếu bạn là tác giả) yêu cầu phiên còn hiệu lực.</li></ul><h2>Sự cố thường gặp</h2><ul><li><strong>Sai mật khẩu</strong>: kiểm tra bật tắt caps lock, thử nhập lại; nếu vẫn lỗi, dùng <strong>Quên mật khẩu</strong>.</li><li><strong>Tài khoản chưa xác nhận email</strong>: hoàn tất bước xác nhận trong hộp thư hoặc gửi lại email xác nhận.</li><li><strong>Quá nhiều lần thử</strong>: hệ thống có thể tạm giới hạn tần suất để chống brute-force; hãy đợi vài phút rồi thử lại.</li></ul>$body$::text, '10000000-0000-4000-8000-000000000012'::uuid, '10000000-0000-4000-8000-000000000001'::uuid, 'published', '2026-05-10T08:45:00Z'::timestamptz, '2026-05-10T08:45:00Z'::timestamptz, 1, 'Đăng nhập — Email, mật khẩu và Google', 'Hướng dẫn đăng nhập và xử lý sự cố thường gặp.', ARRAY['đăng nhập','Google OAuth','PLC Việt Nam']::text[], 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, excerpt = EXCLUDED.excerpt, content = EXCLUDED.content, category_id = EXCLUDED.category_id, field_id = EXCLUDED.field_id, status = EXCLUDED.status, published_at = EXCLUDED.published_at, updated_at = EXCLUDED.updated_at, reading_time = EXCLUDED.reading_time, seo_title = EXCLUDED.seo_title, seo_description = EXCLUDED.seo_description, seo_keywords = EXCLUDED.seo_keywords;
INSERT INTO public.post_tags (post_id, tag_id) SELECT id, '10000000-0000-4000-8000-000000000099'::uuid FROM public.posts WHERE slug = 'reader-dang-nhap-email-mat-khau-va-google' ON CONFLICT DO NOTHING;
INSERT INTO public.posts (id, slug, title, excerpt, content, category_id, field_id, status, published_at, updated_at, reading_time, seo_title, seo_description, seo_keywords, view_count) VALUES ('10000000-0000-4000-8000-000000001005'::uuid, 'reader-dang-xuat-va-bao-mat-phien', 'Đăng xuất, phiên làm việc và thiết bị dùng chung', 'Cách đăng xuất an toàn, quản lý phiên trên nhiều thiết bị và thói quen tốt khi dùng máy công cộng.', $body$<h2>Đăng xuất ở đâu?</h2><p>Mở <strong>menu tài khoản</strong> (góc trên, biểu tượng người dùng) và chọn <strong>Đăng xuất</strong>. Thao tác này kết thúc phiên trên trình duyệt hiện tại theo cơ chế mà ứng dụng triển khai (Supabase session).</p><h2>Vì sao đăng xuất quan trọng?</h2><p>Trên <strong>máy tính dùng chung</strong>, đăng xuất giúp người khác không truy cập bình luận hoặc thông tin cá nhân dưới danh nghĩa bạn. Trên điện thoại cá nhân, đăng xuất hữu ích khi bạn chuyển nhượng thiết bị hoặc sửa chữa.</p><h2>Phiên và cookie</h2><p>Đăng nhập thường dựa trên <strong>cookie / bộ nhớ trình duyệt</strong>. Xóa cookie trang web có thể đưa bạn về trạng thái chưa đăng nhập. Điều này là bình thường và không có nghĩa tài khoản bị xóa.</p><h2>Thói quen đề xuất</h2><ul><li>Đăng xuất trước khi rời máy tính công cộng.</li><li>Không lưu mật khẩu trên trình duyệt dùng chung nếu không tin cậy.</li><li>Nếu nghi ngờ phiên bị lộ, <strong>đổi mật khẩu</strong> sau khi đăng nhập lại trên thiết bị an toàn.</li></ul>$body$::text, '10000000-0000-4000-8000-000000000012'::uuid, '10000000-0000-4000-8000-000000000001'::uuid, 'published', '2026-05-10T09:00:00Z'::timestamptz, '2026-05-10T09:00:00Z'::timestamptz, 1, 'Đăng xuất và bảo mật phiên', 'Hướng dẫn đăng xuất an toàn và thói quen trên thiết bị dùng chung.', ARRAY['đăng xuất','bảo mật','phiên']::text[], 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, excerpt = EXCLUDED.excerpt, content = EXCLUDED.content, category_id = EXCLUDED.category_id, field_id = EXCLUDED.field_id, status = EXCLUDED.status, 