INSERT INTO public.posts (id, slug, title, excerpt, content, category_id, field_id, status, published_at, updated_at, reading_time, seo_title, seo_description, seo_keywords, view_count) VALUES ('10000000-0000-4000-8000-000000001006'::uuid, 'reader-quen-mat-khau-va-email-khoi-phuc', 'Quên mật khẩu — Gửi email khôi phục và giới hạn tần suất', 'Cách yêu cầu liên kết đặt lại mật khẩu, kiểm tra hộp thư và hiểu thời gian chờ giữa các lần gửi.', $body$<h2>Bắt đầu từ trang Quên mật khẩu</h2><p>Trên màn hình đăng nhập, chọn <strong>Quên mật khẩu</strong> (hoặc liên kết tương đương). Nhập <strong>email đã đăng ký</strong> và gửi yêu cầu.</p><h2>Điều gì xảy ra phía sau?</h2><p>Hệ thống gửi email chứa <strong>liên kết đặt lại mật khẩu</strong> có thời hạn. Vì lý do bảo mật, thông báo hiển thị cho người dùng thường <strong>trung tính</strong> (không tiết lộ email có tồn tại hay không) để giảm <em>enumeration</em> tài khoản.</p><h2>Kiểm tra hộp thư</h2><ul><li>Chờ vài phút; kiểm tra thư mục spam.</li><li>Chỉ bấm liên kết từ nguồn bạn tin cậy và khớp với tên miền chính thức của blog.</li></ul><h2>Giới hạn tần suất (cooldown)</h2><p>Để chống lạm dụng, blog có thể giới hạn số lần gửi lại email khôi phục trong một khoảng thời gian (ví dụ <strong>60 giây</strong> giữa các lần gửi với cùng email). Nếu bạn vừa gửi, hãy đợi đến khi hết thời gian chờ trước khi thử lại.</p><h2>Nếu vẫn không nhận được thư</h2><ul><li>Xác nhận bạn gõ đúng email đã dùng lúc đăng ký.</li><li>Thử địa chỉ email thay thế nếu bạn có nhiều hồ sơ.</li><li>Liên hệ quản trị qua kênh chính thức của tổ chức nếu tường lửa công ty chặn email xác thực.</li></ul>$body$::text, '10000000-0000-4000-8000-000000000013'::uuid, '10000000-0000-4000-8000-000000000001'::uuid, 'published', '2026-05-10T09:15:00Z'::timestamptz, '2026-05-10T09:15:00Z'::timestamptz, 1, 'Quên mật khẩu và email khôi phục', 'Hướng dẫn gửi email đặt lại mật khẩu và cooldown.', ARRAY['quên mật khẩu','khôi phục']::text[], 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, excerpt = EXCLUDED.excerpt, content = EXCLUDED.content, category_id = EXCLUDED.category_id, field_id = EXCLUDED.field_id, status = EXCLUDED.status, published_at = EXCLUDED.published_at, updated_at = EXCLUDED.updated_at, reading_time = EXCLUDED.reading_time, seo_title = EXCLUDED.seo_title, seo_description = EXCLUDED.seo_description, seo_keywords = EXCLUDED.seo_keywords;
