INSERT INTO public.posts (id, slug, title, excerpt, content, category_id, field_id, status, published_at, updated_at, reading_time, seo_title, seo_description, seo_keywords, view_count) VALUES ('10000000-0000-4000-8000-000000001007'::uuid, 'reader-dat-lai-mat-khau-sau-lien-ket', 'Đặt lại mật khẩu sau khi nhận liên kết', 'Mở liên kết, đặt mật khẩu mới đủ mạnh, xác nhận khớp và hoàn tất đăng nhập lại.', $body$<h2>Sau khi bấm liên kết trong email</h2><p>Trình duyệt mở trang <strong>đặt lại mật khẩu</strong>. Tùy cấu hình, phiên xác thực có thể được thiết lập qua mã trong URL hoặc luồng callback — bạn chỉ cần làm theo hướng dẫn trên màn hình.</p><h2>Quy tắc mật khẩu</h2><p>Hệ thống thường yêu cầu mật khẩu đạt <strong>độ dài tối thiểu</strong> và gồm <strong>chữ hoa, chữ thường, chữ số và ký tự đặc biệt</strong>. Đây là chuẩn phổ biến để giảm rủi ro dò mật khẩu.</p><h2>Ô “Mật khẩu” và “Xác nhận mật khẩu”</h2><p>Hai ô phải <strong>khớp hoàn toàn</strong>. Máy chủ cũng kiểm tra khớp để tránh lỗi do gửi trực tiếp API.</p><h2>Sau khi đổi mật khẩu thành công</h2><ul><li>Đăng nhập lại bằng email và mật khẩu mới.</li><li>Cập nhật mật khẩu trong <strong>trình quản lý mật khẩu</strong> cá nhân (được khuyến nghị).</li><li>Nếu bạn đang đăng nhập ở thiết bị khác, có thể cần đăng nhập lại ở đó.</li></ul><h2>Lưu ý an ninh</h2><p>Không chia sẻ liên kết đặt lại mật khẩu cho người khác. Nếu bạn <strong>không</strong> yêu cầu đặt lại mà vẫn nhận email, hãy bỏ qua và kiểm tra bảo mật email.</p>$body$::text, '10000000-0000-4000-8000-000000000013'::uuid, '10000000-0000-4000-8000-000000000001'::uuid, 'published', '2026-05-10T09:30:00Z'::timestamptz, '2026-05-10T09:30:00Z'::timestamptz, 1, 'Đặt lại mật khẩu — Hướng dẫn chi tiết', 'Đặt mật khẩu mới an toàn sau liên kết khôi phục.', ARRAY['đặt lại mật khẩu','reset password']::text[], 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, excerpt = EXCLUDED.excerpt, content = EXCLUDED.content, category_id = EXCLUDED.category_id, field_id = EXCLUDED.field_id, status = EXCLUDED.status, published_at = EXCLUDED.published_at, updated_at = EXCLUDED.updated_at, reading_time = EXCLUDED.reading_time, seo_title = EXCLUDED.seo_title, seo_description = EXCLUDED.seo_description, seo_keywords = EXCLUDED.seo_keywords;
