INSERT INTO public.posts (id, slug, title, excerpt, content, category_id, field_id, status, published_at, updated_at, reading_time, seo_title, seo_description, seo_keywords, view_count) VALUES ('10000000-0000-4000-8000-000000001008'::uuid, 'reader-xac-nhan-email-gui-lai-va-chinh-sach', 'Xác nhận email khi đăng ký — Gửi lại thư và chính sách chung', 'Hoàn tất xác nhận sau đăng ký, gửi lại email với thời gian chờ, và các chính sách liên quan (quyền riêng tư, điều khoản).', $body$<h2>Vì sao cần xác nhận email?</h2><p>Xác nhận giúp đảm bảo bạn <strong>sở hữu địa chỉ email</strong> dùng để đăng ký, giảm tài khoản rác và hỗ trợ khôi phục tài khoản đúng người.</p><h2>Sau khi đăng ký</h2><ol><li>Kiểm tra hộp thư và mở email xác nhận.</li><li>Bấm nút hoặc liên kết trong thư.</li><li>Khi thành công, bạn có thể đăng nhập đầy đủ tính năng phụ thuộc xác thực.</li></ol><h2>Gửi lại email xác nhận</h2><p>Nếu hết hạn hoặc mất thư, dùng tùy chọn <strong>Gửi lại</strong> trên màn hình hướng dẫn (nếu có). Giống luồng quên mật khẩu, hệ thống có thể áp dụng <strong>cooldown</strong> giữa các lần gửi để tránh spam.</p><h2>Chính sách và điều khoản</h2><p>Trên blog có các trang <strong>Chính sách quyền riêng tư</strong> và <strong>Điều khoản sử dụng</strong>. Bạn nên đọc để hiểu cách dữ liệu được xử lý và quy tắc hành vi khi bình luận hoặc tương tác.</p><h2>Gợi ý thực hành</h2><ul><li>Giữ một địa chỉ email ổn định cho tài khoản.</li><li>Bật xác thực hai lớp cho email (tại nhà cung cấp hộp thư) nếu có thể.</li><li>Không đăng công khai liên kết xác nhận hoặc liên kết đặt lại mật khẩu.</li></ul><p>Chúc bạn sử dụng PLC Việt Nam hiệu quả — từ đọc nội dung đến tham gia cộng đồng một cách an toàn.</p>$body$::text, '10000000-0000-4000-8000-000000000013'::uuid, '10000000-0000-4000-8000-000000000001'::uuid, 'published', '2026-05-10T09:45:00Z'::timestamptz, '2026-05-10T09:45:00Z'::timestamptz, 1, 'Xác nhận email và gửi lại thư', 'Hoàn tất xác nhận đăng ký, gửi lại email và liên kết chính sách.', ARRAY['xác nhận email','điều khoản','quyền riêng tư']::text[], 0) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, excerpt = EXCLUDED.excerpt, content = EXCLUDED.content, category_id = EXCLUDED.category_id, field_id = EXCLUDED.field_id, status = EXCLUDED.status, published_at = EXCLUDED.published_at, updated_at = EXCLUDED.updated_at, reading_time = EXCLUDED.reading_time, seo_title = EXCLUDED.seo_title, seo_description = EXCLUDED.seo_description, seo_keywords = EXCLUDED.seo_keywords;
